import { useEffect, useMemo, useRef, useState, type FormEvent, type ReactNode } from 'react';
import { ArrowDownToLine, ArrowUpRight, CalendarDays, Check, ChevronRight, FileSpreadsheet, FileText, History as HistoryIcon, Info, Plus, Search, Settings2, Target, Trophy, Users, Wallet, X } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import type { Analytics, AppData, Period, Sale, Seller, SellerMetric, Settings, User } from '../../shared/types';
import { api } from '../lib/api';
import { dateLabel, integer, money, percent, shortMoney } from '../lib/format';
import './Management.css';

export interface ManagementProps {
  data: AppData; analytics: Analytics; period: Period; user: User;
  onData: (data: AppData) => void; notify: (message: string, type?: 'success' | 'error') => void;
}

const statusLabels = { valid: 'Confirmada', cancelled: 'Cancelada', returned: 'Devolvida' };
const inputMoney = (cents: number) => (cents / 100).toFixed(2).replace('.', ',');
function currencyValue(value: string): number {
  const trimmed = value.trim().replace(/^R\$\s*/, '').replace(/\s/g, '');
  if (!trimmed || !/^\d[\d.,]*$/.test(trimmed)) throw new Error('Informe um valor monetário válido, como 1.500,00.');
  let normalized: string;
  if (trimmed.includes(',')) {
    if (!/^\d{1,3}(\.\d{3})*(,\d{1,2})?$/.test(trimmed) && !/^\d+(,\d{1,2})?$/.test(trimmed)) throw new Error('Use até duas casas decimais no valor.');
    normalized = trimmed.replace(/\./g, '').replace(',', '.');
  } else if (/^\d{1,3}(\.\d{3})+$/.test(trimmed)) normalized = trimmed.replace(/\./g, '');
  else {
    if (!/^\d+(\.\d{1,2})?$/.test(trimmed)) throw new Error('Use até duas casas decimais no valor.');
    normalized = trimmed;
  }
  const result = Math.round(Number(normalized) * 100);
  if (!Number.isSafeInteger(result) || result > 100_000_000_000) throw new Error('O valor informado é muito alto.');
  return result;
}

function timestampLabel(value: string) { const date = new Date(value); return Number.isNaN(date.getTime()) ? '—' : new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: 'America/Sao_Paulo' }).format(date); }
function errorMessage(error: unknown) { return error instanceof Error ? error.message : 'Não foi possível concluir a operação.'; }
function updateData(result: { data: AppData }, props: ManagementProps) { props.onData(result.data); }
function Heading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="page-heading"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p className="muted">{description}</p></div>{action}</div>;
}
function Empty({ title, children, icon = <FileText size={25} /> }: { title: string; children: ReactNode; icon?: ReactNode }) {
  return <div className="empty-state management-empty"><span className="empty-icon">{icon}</span><h3>{title}</h3><p className="muted">{children}</p></div>;
}
function Notice({ children }: { children: ReactNode }) { return <div className="management-notice"><Info size={17} /><span>{children}</span></div>; }
function Metric({ label, value, note, icon }: { label: string; value: ReactNode; note?: ReactNode; icon?: ReactNode }) {
  return <div className="stat-card management-stat"><div className="management-stat-title">{label}{icon}</div><strong>{value}</strong>{note && <span className="muted">{note}</span>}</div>;
}
function SellerName({ seller }: { seller: Seller }) {
  return <span className="seller-identity"><span className="avatar" style={{ background: `${seller.color}18`, color: seller.color }}>{seller.initials || seller.name.slice(0, 2).toUpperCase()}</span><span>{seller.name}{!seller.active && <small className="muted">Inativo</small>}</span></span>;
}
function Modal({ title, children, onClose, wide = false }: { title: string; children: ReactNode; onClose: () => void; wide?: boolean }) {
  const dialog = useRef<HTMLDialogElement>(null);
  useEffect(() => { const el = dialog.current; el?.showModal(); return () => el?.close(); }, []);
  return <dialog className={`management-modal ${wide ? 'management-modal-wide' : ''}`} ref={dialog} onCancel={onClose} aria-label={title} onClick={event => { if (event.target === event.currentTarget) onClose(); }}>
    <div className="modal-heading"><h2>{title}</h2><button className="icon-btn" type="button" aria-label="Fechar" onClick={onClose}><X size={20} /></button></div>{children}
  </dialog>;
}

export function SalesPage(props: ManagementProps) {
  const { data, period, user } = props;
  const [sellerId, setSellerId] = useState(''); const [status, setStatus] = useState('valid'); const [query, setQuery] = useState('');
  const [selected, setSelected] = useState<Sale[] | null>(null);
  const [page, setPage] = useState(1);
  const transactions = useMemo(() => {
    const groups = new Map<string, Sale[]>();
    data.sales.filter(s => s.date >= period.from && s.date <= period.to && (!sellerId || s.sellerId === sellerId) && (!status || s.status === status) && (user.role === 'admin' || s.sellerId === user.sellerId) && (!query || `${s.product} ${s.externalId} ${s.category}`.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')))).forEach(sale => {
      const key = sale.externalId ? `${sale.date}|${sale.sellerId}|${sale.externalId}` : sale.id;
      groups.set(key, [...(groups.get(key) || []), sale]);
    });
    return [...groups.values()].sort((a, b) => `${b[0].date}${b[0].time}`.localeCompare(`${a[0].date}${a[0].time}`));
  }, [data.sales, period.from, period.to, sellerId, status, query, user]);
  useEffect(() => { setPage(1); }, [sellerId, status, query, period.from, period.to]);
  const total = transactions.reduce((sum, rows) => sum + rows.reduce((s, row) => s + row.netCents, 0), 0);
  const pages = Math.max(1, Math.ceil(transactions.length / 20));
  return <>
    <Heading eyebrow="Operação" title="Vendas" description="Cada venda, cada detalhe. Acompanhe o que movimenta a loja." />
    <div className="stat-grid management-three"><Metric label="Vendas no filtro" value={integer(transactions.length)} icon={<FileText size={18} />} /><Metric label="Valor das vendas" value={money(total)} note="Soma dos itens exibidos no filtro" icon={<Wallet size={18} />} /><Metric label="Ticket médio" value={transactions.length ? money(Math.round(total / transactions.length)) : '—'} note="Valor médio por transação" icon={<ArrowUpRight size={18} />} /></div>
    {data.summaries.some(s => s.startDate <= period.to && s.endDate >= period.from) && <Notice>O período contém dados consolidados. Eles compõem os indicadores, mas não possuem itens individuais para exibir nesta tabela.</Notice>}
    <section className="panel"><div className="section-header"><div><h2>Registro de vendas</h2><p className="muted">{integer(transactions.length)} transações encontradas</p></div></div>
      <div className="management-filters"><label className="management-search"><Search size={17} /><input aria-label="Buscar venda" placeholder="Buscar produto ou nº da venda" value={query} onChange={e => setQuery(e.target.value)} /></label>
        {user.role === 'admin' && <select aria-label="Filtrar vendedor" value={sellerId} onChange={e => setSellerId(e.target.value)}><option value="">Todos os vendedores</option>{data.sellers.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select>}
        <select aria-label="Filtrar status da venda" value={status} onChange={e => setStatus(e.target.value)}><option value="">Todos os status</option><option value="valid">Confirmadas</option><option value="cancelled">Canceladas</option><option value="returned">Devolvidas</option></select>
      </div>
      {!transactions.length ? <Empty title="Nenhuma venda por aqui">Importe as vendas ou ajuste os filtros para consultar suas transações.</Empty> : <><div className="table-wrap"><table className="data-table"><thead><tr><th>Venda / data</th><th>Vendedor</th><th>Produtos</th><th>Pagamento</th><th>Valor líquido</th><th>Status</th><th aria-label="Detalhes" /></tr></thead><tbody>{transactions.slice((page - 1) * 20, page * 20).map(rows => {
        const first = rows[0]; const seller = data.sellers.find(s => s.id === first.sellerId);
        return <tr key={first.id}><td><strong>{first.externalId || 'Sem número'}</strong><small className="muted">{dateLabel(first.date)} {first.time}</small></td><td>{seller ? <SellerName seller={seller} /> : 'Sem identificação'}</td><td className="product-cell"><span>{rows.map(s => s.product).filter(Boolean).join(', ') || 'Produto não informado'}</span><small className="muted">{rows.reduce((sum, row) => sum + row.quantity, 0)} unidade(s)</small></td><td>{[...new Set(rows.map(s => s.paymentMethod).filter(Boolean))].join(', ') || 'Não informado'}</td><td className="nowrap"><strong>{money(rows.reduce((sum, s) => sum + s.netCents, 0))}</strong></td><td><span className={`badge ${first.status === 'valid' ? 'badge-success' : 'badge-danger'}`}>{statusLabels[first.status]}</span></td><td><button className="icon-btn" aria-label={`Detalhes da venda ${first.externalId || dateLabel(first.date)}`} onClick={() => setSelected(rows)}><ChevronRight size={18} /></button></td></tr>;
      })}</tbody></table></div><div className="management-pagination"><span className="muted">Página {page} de {pages}</span><div><button className="btn btn-ghost" disabled={page === 1} onClick={() => setPage(p => p - 1)}>Anterior</button><button className="btn btn-ghost" disabled={page === pages} onClick={() => setPage(p => p + 1)}>Próxima</button></div></div></>}
    </section>
    {selected && <Modal title={`Venda ${selected[0].externalId || 'sem número'}`} onClose={() => setSelected(null)} wide><p className="muted">{dateLabel(selected[0].date)} · {data.sellers.find(s => s.id === selected[0].sellerId)?.name || 'Vendedor não identificado'}</p><div className="table-wrap"><table className="data-table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Bruto</th><th>Desconto</th><th>Líquido</th></tr></thead><tbody>{selected.map(s => <tr key={s.id}><td>{s.product || 'Não informado'}<small className="muted">{s.category}</small></td><td>{s.quantity}</td><td>{money(s.grossCents)}</td><td>{money(s.discountCents)}</td><td>{money(s.netCents)}</td></tr>)}</tbody></table></div><div className="sale-breakdown"><span>Troca recebida <strong>{money(selected.reduce((sum, s) => sum + s.tradeInCents, 0))}</strong></span><span>Valor financiado <strong>{money(selected.reduce((sum, s) => sum + s.financedCents, 0))}</strong></span><span>Total líquido <strong>{money(selected.reduce((sum, s) => sum + s.netCents, 0))}</strong></span></div></Modal>}
  </>;
}

function SellerEditor({ seller, props, onClose }: { seller?: Seller; props: ManagementProps; onClose: () => void }) {
  const [name, setName] = useState(seller?.name || ''); const [goal, setGoal] = useState(inputMoney(seller?.monthlyGoalCents || 0)); const [color, setColor] = useState(seller?.color || '#0d9488'); const [active, setActive] = useState(seller?.active ?? true); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function save(event: FormEvent) { event.preventDefault(); setError(''); setBusy(true); try { const payload = { ...(seller || {}), name: name.trim(), initials: name.trim().split(/\s+/).filter(Boolean).map(s => s[0]).slice(0, 2).join('').toUpperCase(), color, active, monthlyGoalCents: currencyValue(goal) }; if (!payload.name) throw new Error('Informe o nome do vendedor.'); const result = await api<{ data: AppData }>(seller ? `/api/sellers/${seller.id}` : '/api/sellers', { method: seller ? 'PUT' : 'POST', body: JSON.stringify(payload) }); updateData(result, props); props.notify(seller ? 'Vendedor atualizado.' : 'Vendedor cadastrado.'); onClose(); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } }
  return <Modal title={seller ? 'Editar vendedor' : 'Novo vendedor'} onClose={onClose}><form onSubmit={save} className="management-form"><label className="field">Nome completo<input required minLength={2} maxLength={80} value={name} onChange={e => setName(e.target.value)} placeholder="Nome do vendedor" autoFocus /></label><label className="field">Meta mensal padrão (R$)<input required inputMode="decimal" value={goal} onChange={e => setGoal(e.target.value)} /></label><label className="field">Cor de identificação<input type="color" value={color} onChange={e => setColor(e.target.value)} /></label><label className="check-field"><input type="checkbox" checked={active} onChange={e => setActive(e.target.checked)} />Vendedor ativo</label>{error && <p className="form-error" role="alert">{error}</p>}<div className="modal-actions"><button className="btn btn-ghost" type="button" onClick={onClose}>Cancelar</button><button className="btn btn-primary" disabled={busy} type="submit">{busy ? 'Salvando…' : 'Salvar vendedor'}</button></div></form></Modal>;
}

function UserEditor({ props, onClose }: { props: ManagementProps; onClose: () => void }) {
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [sellerId, setSellerId] = useState(props.data.sellers.find(s => s.active)?.id || ''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function save(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const result = await api<{ data: AppData }>('/api/users', { method: 'POST', body: JSON.stringify({ name: name.trim(), email: email.trim(), password, sellerId, role: 'seller' }) }); if (result.data) updateData(result, props); props.notify('Acesso do vendedor criado.'); onClose(); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } }
  return <Modal title="Criar acesso de vendedor" onClose={onClose}><form onSubmit={save} className="management-form"><p className="muted">O vendedor verá os próprios resultados e o ranking agregado da equipe.</p><label className="field">Nome de acesso<input required minLength={2} maxLength={80} autoComplete="name" value={name} onChange={e => setName(e.target.value)} /></label><label className="field">E-mail<input required type="email" maxLength={254} autoComplete="email" value={email} onChange={e => setEmail(e.target.value)} /></label><label className="field">Senha inicial<input required type="password" minLength={10} maxLength={128} autoComplete="new-password" value={password} onChange={e => setPassword(e.target.value)} /><small className="muted">Pelo menos 10 caracteres.</small></label><label className="field">Vendedor vinculado<select required value={sellerId} onChange={e => setSellerId(e.target.value)}><option value="">Selecione o vendedor</option>{props.data.sellers.filter(s => s.active).map(s => <option key={s.id} value={s.id}>{s.name}</option>)}</select></label>{error && <p role="alert" className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={onClose}>Cancelar</button><button type="submit" className="btn btn-primary" disabled={busy || !sellerId}>{busy ? 'Criando…' : 'Criar acesso'}</button></div></form></Modal>;
}

export function SellersPage(props: ManagementProps) {
  const [editing, setEditing] = useState<Seller | 'new' | null>(null); const [access, setAccess] = useState(false); const { data, analytics, user } = props;
  return <><Heading eyebrow="Pessoas" title="Equipe de vendas" description="Pessoas no centro. Metas claras para cada conquista." action={user.role === 'admin' && <div className="management-actions"><button className="btn btn-ghost" onClick={() => setAccess(true)} disabled={!data.sellers.some(s => s.active)}>Criar acesso</button><button className="btn btn-primary" onClick={() => setEditing('new')}><Plus size={17} />Novo vendedor</button></div>} /><section className="panel"><div className="section-header"><div><h2>Seus vendedores</h2><p className="muted">{data.sellers.filter(s => s.active).length} ativos · resultados do período selecionado</p></div><Users size={20} /></div>{!data.sellers.length ? <Empty title="Sua equipe começa aqui" icon={<Users size={25} />}>Cadastre os vendedores antes de importar as vendas e acompanhar o desempenho.</Empty> : <div className="table-wrap"><table className="data-table"><thead><tr><th>Vendedor</th><th>Faturamento</th><th>Vendas</th><th>Meta mensal padrão</th><th>Status</th>{user.role === 'admin' && <th />}</tr></thead><tbody>{data.sellers.filter(s => user.role === 'admin' || s.id === user.sellerId).map(seller => { const metric = analytics.sellers.find(s => s.seller.id === seller.id); return <tr key={seller.id}><td><SellerName seller={seller} /></td><td>{money(metric?.revenueCents || 0)}</td><td>{integer(metric?.count || 0)}</td><td>{seller.monthlyGoalCents ? money(seller.monthlyGoalCents) : <span className="muted">Não definida</span>}</td><td><span className={`badge ${seller.active ? 'badge-success' : ''}`}>{seller.active ? 'Ativo' : 'Inativo'}</span></td>{user.role === 'admin' && <td><button className="btn btn-ghost" onClick={() => setEditing(seller)}>Editar</button></td>}</tr>; })}</tbody></table></div>}</section>{editing && <SellerEditor seller={editing === 'new' ? undefined : editing} props={props} onClose={() => setEditing(null)} />}{access && <UserEditor props={props} onClose={() => setAccess(false)} />}</>;
}

function CompanyGoalEditor({ props, onClose, seller }: { props: ManagementProps; onClose: () => void; seller?: Seller }) {
  const month = props.period.from.slice(0, 7);
  const savedMonth = props.data.settings.goalsByMonth?.[month];
  const initialGoal = seller ? savedMonth?.sellerCents[seller.id] ?? seller.monthlyGoalCents : savedMonth?.companyCents ?? props.data.settings.monthlyGoalCents;
  const [goal, setGoal] = useState(inputMoney(initialGoal)); const [ticket, setTicket] = useState(inputMoney(props.data.settings.ticketGoalCents)); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  async function save(event: FormEvent) {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const settings = props.data.settings;
      const monthGoals = { companyCents: savedMonth?.companyCents ?? settings.monthlyGoalCents, sellerCents: { ...Object.fromEntries(props.data.sellers.map(s => [s.id, s.monthlyGoalCents])), ...savedMonth?.sellerCents } };
      if (seller) monthGoals.sellerCents[seller.id] = currencyValue(goal); else monthGoals.companyCents = currencyValue(goal);
      const result = await api<{ data: AppData }>('/api/settings', { method: 'PUT', body: JSON.stringify({ ...settings, ...(!seller ? { ticketGoalCents: currencyValue(ticket) } : {}), goalsByMonth: { ...settings.goalsByMonth, [month]: monthGoals } }) });
      updateData(result, props); props.notify(`Meta de ${month.split('-').reverse().join('/')} atualizada.`); onClose();
    } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); }
  }
  return <Modal title={seller ? `Meta de ${seller.name}` : 'Definir metas da loja'} onClose={onClose}><form onSubmit={save} className="management-form"><Notice>Competência: <strong>{month.split('-').reverse().join('/')}</strong>. A meta de faturamento será salva apenas para este mês.</Notice><label className="field">Meta mensal de faturamento (R$)<input inputMode="decimal" value={goal} onChange={e => setGoal(e.target.value)} required /></label>{!seller && <label className="field">Meta geral de ticket médio (R$)<input inputMode="decimal" value={ticket} onChange={e => setTicket(e.target.value)} required /><small className="muted">A meta de ticket é uma configuração geral da loja.</small></label>}<p className="muted">Use zero para deixar uma meta sem definição. O calendário de funcionamento está em Configurações.</p>{error && <p role="alert" className="form-error">{error}</p>}<div className="modal-actions"><button type="button" className="btn btn-ghost" onClick={onClose}>Cancelar</button><button type="submit" className="btn btn-primary" disabled={busy}>{busy ? 'Salvando…' : 'Salvar metas'}</button></div></form></Modal>;
}

export function GoalsPage(props: ManagementProps) {
  const { data, analytics, user } = props; const [companyEditor, setCompanyEditor] = useState(false); const [sellerEditor, setSellerEditor] = useState<Seller | null>(null);
  return <><Heading eyebrow="Direção" title="Metas e conquistas" description="Transforme o objetivo do mês em próximos passos possíveis." action={user.role === 'admin' && <button className="btn btn-primary" onClick={() => setCompanyEditor(true)}><Settings2 size={16} />Definir metas</button>} />
    <div className="stat-grid management-three"><Metric label={user.role === 'seller' ? 'Sua meta no período' : 'Meta do período'} value={analytics.goalCents ? money(analytics.goalCents) : 'Não definida'} icon={<Target size={18} />} note={user.role === 'admin' ? `Competência: ${props.period.from.slice(0, 7).split('-').reverse().join('/')}` : 'Calculada a partir da sua meta mensal'} /><Metric label="Atingimento" value={analytics.goalCents ? percent(analytics.percentage) : '—'} note={`${money(analytics.revenueCents)} realizados`} icon={<ArrowUpRight size={18} />} /><Metric label="Necessário por dia útil" value={analytics.goalCents ? money(analytics.neededDailyCents) : '—'} note={`${analytics.remainingDays} dias úteis restantes no período`} icon={<CalendarDays size={18} />} /></div>
    {!analytics.goalCents && <Notice>{user.role === 'admin' ? 'Defina as metas da loja e dos vendedores para acompanhar o atingimento e a projeção.' : 'Sua meta ainda não foi definida. Solicite a configuração ao administrador.'}</Notice>}
    <section className="panel"><div className="section-header"><div><h2>Metas por vendedor</h2><p className="muted">Progresso com base nas vendas válidas do período</p></div><Target size={20} /></div>{!analytics.sellers.length ? <Empty title="Nenhuma meta para acompanhar" icon={<Target size={25} />}>Cadastre sua equipe e defina as metas mensais.</Empty> : <div className="goals-list">{analytics.sellers.filter(m => user.role === 'admin' || m.seller.id === user.sellerId).map(metric => <div className="goal-row" key={metric.seller.id}><div className="goal-row-heading"><SellerName seller={metric.seller} /><div><strong>{money(metric.revenueCents)}</strong><span className="muted"> / {metric.goalCents ? money(metric.goalCents) : 'meta pendente'}</span></div>{user.role === 'admin' && <button className="btn btn-ghost" onClick={() => setSellerEditor(metric.seller)}>Editar meta</button>}</div><div className="progress-track"><span style={{ width: `${metric.goalCents ? Math.min(100, Math.max(0, metric.percentage)) : 0}%`, background: metric.seller.color }} /></div><div className="goal-row-foot"><span className="muted">{metric.goalCents ? `${percent(metric.percentage)} atingidos` : 'Defina uma meta para medir o progresso'}</span><span>{metric.goalCents ? metric.remainingCents > 0 ? `Faltam ${money(metric.remainingCents)}` : 'Meta conquistada' : '—'}</span></div></div>)}</div>}</section>
    {companyEditor && <CompanyGoalEditor props={props} onClose={() => setCompanyEditor(false)} />}{sellerEditor && <CompanyGoalEditor seller={sellerEditor} props={props} onClose={() => setSellerEditor(null)} />}
  </>;
}

type RankingMetric = 'revenue' | 'percentage' | 'count' | 'ticket';
export function RankingPage(props: ManagementProps) {
  const { data, analytics, period, user } = props; const [sort, setSort] = useState<RankingMetric>('revenue'); const [remote, setRemote] = useState<Array<{ sellerId: string; revenueCents: number; count: number }> | null>(null); const [error, setError] = useState('');
  useEffect(() => { if (user.role !== 'seller') return; let active = true; setRemote(null); setError(''); api<{ ranking: Array<{ sellerId: string; revenueCents: number; count: number }> }>(`/api/ranking?from=${period.from}&to=${period.to}`).then(result => { if (active) setRemote(result.ranking); }).catch(err => { if (active) setError(errorMessage(err)); }); return () => { active = false; }; }, [user.role, period.from, period.to]);
  const metrics = useMemo(() => {
    if (user.role === 'admin') return analytics.sellers;
    if (!remote) return [];
    return remote.flatMap(row => { const seller = data.sellers.find(s => s.id === row.sellerId); if (!seller) return []; const ownMetric = analytics.sellers.find(s => s.seller.id === seller.id); const goalCents = ownMetric?.goalCents ?? data.settings.goalsByMonth?.[period.from.slice(0, 7)]?.sellerCents[seller.id] ?? seller.monthlyGoalCents; return [{ seller, revenueCents: row.revenueCents, count: row.count, ticketCents: row.count ? Math.round(row.revenueCents / row.count) : 0, goalCents, percentage: goalCents ? row.revenueCents / goalCents * 100 : 0, remainingCents: Math.max(0, goalCents - row.revenueCents), neededDailyCents: 0, rank: 0 }]; });
  }, [analytics.sellers, data.sellers, data.settings, period.from, remote, user.role]);
  const value = (m: SellerMetric) => sort === 'revenue' ? m.revenueCents : sort === 'percentage' ? m.percentage : sort === 'count' ? m.count : m.ticketCents;
  const ranked = [...metrics].filter(m => m.seller.active || m.revenueCents > 0).sort((a, b) => value(b) - value(a) || a.seller.name.localeCompare(b.seller.name));
  const hasActivity = ranked.some(m => m.count > 0 || m.revenueCents > 0); const labels = { revenue: 'Faturamento', percentage: 'Atingimento da meta', count: 'Quantidade de vendas', ticket: 'Ticket médio' }; const formatted = (m: SellerMetric) => sort === 'percentage' ? (m.goalCents ? percent(m.percentage) : 'Sem meta') : sort === 'count' ? integer(m.count) : money(value(m));
  return <><Heading eyebrow="Conquistas da equipe" title="Ranking de vendedores" description="Reconheça resultados e acompanhe a evolução de cada pessoa." /><section className="panel"><div className="section-header"><div><h2>Quem está fazendo acontecer</h2><p className="muted">Classificação por {labels[sort].toLocaleLowerCase('pt-BR')}</p></div><select aria-label="Critério do ranking" value={sort} onChange={e => setSort(e.target.value as RankingMetric)}>{Object.entries(labels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></div>{error ? <Empty title="Não foi possível carregar o ranking">{error}</Empty> : user.role === 'seller' && !remote ? <p className="muted management-loading" role="status">Carregando o ranking…</p> : !hasActivity ? <Empty title="O próximo destaque pode ser você" icon={<Trophy size={26} />}>O ranking aparece após a primeira importação de vendas válidas neste período.</Empty> : <div className="ranking-list">{ranked.map((metric, index) => <div className={`ranking-row ${index === 0 && value(metric) > 0 ? 'ranking-first' : ''}`} key={metric.seller.id}><span className={`rank-position rank-${index + 1}`}>{index === 0 && value(metric) > 0 ? <Trophy size={19} /> : String(index + 1).padStart(2, '0')}</span><div className="ranking-person"><SellerName seller={metric.seller} /><div className="progress-track"><span style={{ width: `${value(ranked[0]) ? Math.max(0, value(metric) / value(ranked[0]) * 100) : 0}%`, background: metric.seller.color }} /></div></div><div className="ranking-value"><strong>{formatted(metric)}</strong><small className="muted">{sort === 'count' ? 'vendas' : `${integer(metric.count)} vendas`}</small></div>{metric.seller.id === user.sellerId && <span className="badge badge-success">Você</span>}</div>)}</div>}</section></>;
}

export function FinancePage({ analytics }: ManagementProps) {
  const financed = analytics.financiers.reduce((sum, f) => sum + f.revenueCents, 0); const operations = analytics.financiers.reduce((sum, f) => sum + f.count, 0); const saleTotal = analytics.financiers.reduce((sum, f) => sum + f.saleTotalCents, 0);
  return <><Heading eyebrow="Parcerias que movem" title="Financeiras" description="Uma visão clara dos financiamentos e da participação de cada parceiro." /><div className="stat-grid management-three"><Metric label="Valor financiado" value={money(financed)} icon={<Wallet size={18} />} note="Somente o crédito contratado" /><Metric label="Operações financiadas" value={integer(operations)} icon={<FileText size={18} />} /><Metric label="Ticket de financiamento" value={operations ? money(Math.round(financed / operations)) : '—'} icon={<ArrowUpRight size={18} />} /></div><Notice>O valor financiado pode ser menor que o valor total da venda. Entradas, pagamentos próprios e aparelhos recebidos em troca não são receita da financeira.</Notice><section className="panel"><div className="section-header"><div><h2>Desempenho por financeira</h2><p className="muted">Participação sobre o valor financiado no período</p></div></div>{!operations ? <Empty title="Nenhum financiamento no período" icon={<Wallet size={25} />}>Importe vendas com o valor financiado e a financeira para acompanhar os parceiros.</Empty> : <div className="table-wrap"><table className="data-table"><thead><tr><th>Financeira</th><th>Valor financiado</th><th>Total das vendas</th><th>Operações</th><th>Ticket financiado</th><th>Participação</th></tr></thead><tbody>{[...analytics.financiers].sort((a, b) => b.revenueCents - a.revenueCents).map(f => <tr key={f.financier.id}><td><strong>{f.financier.name}</strong></td><td>{money(f.revenueCents)}</td><td>{money(f.saleTotalCents)}</td><td>{integer(f.count)}</td><td>{f.count ? money(f.ticketCents) : '—'}</td><td><span className="finance-participation"><span className="progress-track"><span style={{ width: `${Math.min(100, f.percentage)}%` }} /></span>{percent(f.percentage)}</span></td></tr>)}</tbody><tfoot><tr><td>Total</td><td>{money(financed)}</td><td>{money(saleTotal)}</td><td>{integer(operations)}</td><td>{operations ? money(Math.round(financed / operations)) : '—'}</td><td>100%</td></tr></tfoot></table></div>}</section></>;
}

export function TicketPage({ analytics, data, user }: ManagementProps) {
  const goal = data.settings.ticketGoalCents; const visible = analytics.sellers.filter(s => s.count > 0); const ratio = goal && analytics.count ? analytics.ticketCents / goal * 100 : 0;
  return <><Heading eyebrow="Qualidade da venda" title="Ticket médio" description="Entenda o valor de cada atendimento e encontre espaço para crescer." /><div className="stat-grid management-three"><Metric label={user.role === 'admin' ? 'Ticket médio da loja' : 'Seu ticket médio'} value={analytics.count ? money(analytics.ticketCents) : '—'} note={`${integer(analytics.count)} vendas no período`} icon={<ArrowUpRight size={18} />} /><Metric label="Meta de ticket" value={goal ? money(goal) : 'Não definida'} icon={<Target size={18} />} /><Metric label="Atingimento do ticket" value={goal && analytics.count ? percent(ratio) : '—'} note={goal && analytics.count ? ratio >= 100 ? 'Ticket acima da meta estabelecida' : `Faltam ${money(Math.max(0, goal - analytics.ticketCents))} por venda` : 'Defina a meta e importe suas vendas'} icon={<Trophy size={18} />} /></div><section className="panel"><div className="section-header"><div><h2>Ticket por vendedor</h2><p className="muted">Faturamento líquido dividido pelo número de transações</p></div><span className="badge">{visible.length} vendedores com vendas</span></div>{!visible.length ? <Empty title="Vamos conhecer seu ticket?" icon={<ArrowUpRight size={25} />}>Importe as primeiras vendas para comparar o valor médio dos atendimentos.</Empty> : <><div className="ticket-chart" role="img" aria-label="Gráfico do ticket médio por vendedor"><ResponsiveContainer width="100%" height="100%"><BarChart data={visible.map(s => ({ name: s.seller.name.split(' ')[0], ticket: s.ticketCents }))} margin={{ top: 24, right: 30, left: 15, bottom: 0 }}><CartesianGrid vertical={false} stroke="var(--chart-grid)" /><XAxis dataKey="name" tickLine={false} axisLine={false} tick={{ fontSize: 12, fill: 'var(--muted)' }} /><YAxis tickFormatter={value => shortMoney(Number(value))} tickLine={false} axisLine={false} tick={{ fontSize: 11, fill: 'var(--muted)' }} width={82} /><Tooltip formatter={value => [money(Number(value)), 'Ticket médio']} contentStyle={{ borderRadius: 12, border: '1px solid var(--border)', background: 'var(--panel)', color: 'var(--text)', fontSize: 12 }} cursor={{ fill: 'var(--accent-soft)' }} /><Bar dataKey="ticket" fill="var(--accent)" radius={[6, 6, 0, 0]} maxBarSize={58} />{goal > 0 && <ReferenceLine y={goal} stroke="#f59e0b" strokeDasharray="5 4" label={{ value: 'Meta', fill: '#a16207', fontSize: 12, position: 'insideTopRight' }} />}</BarChart></ResponsiveContainer></div><div className="table-wrap"><table className="data-table"><thead><tr><th>Vendedor</th><th>Faturamento</th><th>Vendas</th><th>Ticket médio</th><th>Meta</th></tr></thead><tbody>{[...visible].sort((a, b) => b.ticketCents - a.ticketCents).map(s => <tr key={s.seller.id}><td><SellerName seller={s.seller} /></td><td>{money(s.revenueCents)}</td><td>{integer(s.count)}</td><td><strong>{money(s.ticketCents)}</strong></td><td>{goal ? <span className={`badge ${s.ticketCents >= goal ? 'badge-success' : 'badge-warning'}`}>{percent(s.ticketCents / goal * 100)}</span> : <span className="muted">Não definida</span>}</td></tr>)}</tbody></table></div></>}</section></>;
}

export function InsightsPage({ analytics, data, user, period }: ManagementProps) {
  const insights: Array<{ title: string; text: string; tone: string; action: string }> = [];
  if (analytics.count > 0) {
    if (analytics.goalCents > 0 && analytics.remainingDays > 0 && analytics.pace !== 'no-data') insights.push({ title: analytics.revenueCents >= analytics.goalCents ? 'Objetivo conquistado' : analytics.pace === 'above' ? 'Um ritmo que inspira' : analytics.pace === 'below' ? 'A meta pede atenção' : 'No caminho da meta', text: analytics.revenueCents >= analytics.goalCents ? `Você já alcançou ${percent(analytics.percentage)} da meta do período.` : `Faltam ${money(analytics.remainingCents)} para a meta. Com ${analytics.remainingDays} dias úteis restantes, o ritmo necessário é de ${money(analytics.neededDailyCents)} por dia.`, tone: analytics.pace === 'below' ? 'warning' : 'success', action: 'Acompanhe a necessidade diária e planeje os próximos atendimentos.' });
    if (data.settings.ticketGoalCents > 0) insights.push({ title: analytics.ticketCents >= data.settings.ticketGoalCents ? 'Ticket médio acima da meta' : 'Oportunidade no ticket médio', text: `O ticket atual é ${money(analytics.ticketCents)}, frente à meta de ${money(data.settings.ticketGoalCents)}.`, tone: analytics.ticketCents >= data.settings.ticketGoalCents ? 'success' : 'info', action: analytics.ticketCents >= data.settings.ticketGoalCents ? 'Identifique os atendimentos que contribuíram para este resultado.' : 'Avalie oportunidades relevantes de acessórios e serviços em cada atendimento.' });
    const ranked = [...analytics.sellers].filter(s => s.count > 0).sort((a, b) => b.revenueCents - a.revenueCents);
    if (ranked.length > 1 && user.role === 'admin') insights.push({ title: 'Destaque da equipe', text: `${ranked[0].seller.name} lidera o faturamento com ${money(ranked[0].revenueCents)} em ${integer(ranked[0].count)} vendas.`, tone: 'success', action: 'Compartilhe boas práticas com a equipe e reconheça o progresso.' });
    const missingFinancier = data.sales.filter(s => s.status === 'valid' && s.date >= period.from && s.date <= period.to && s.financedCents > 0 && (!s.financierId || !data.financiers.some(f => f.id === s.financierId))).length;
    if (missingFinancier) insights.push({ title: 'Identificação de financeira pendente', text: `${integer(missingFinancier)} registros financiados na base estão sem uma financeira identificada.`, tone: 'warning', action: 'Revise as colunas e o mapeamento da origem antes da próxima importação.' });
    if (analytics.hasSummaries) insights.push({ title: 'Sua análise contém dados consolidados', text: 'Parte dos resultados vem de totais por vendedor. O detalhamento por produto e financeira não pode ser reconstruído a partir desses totais.', tone: 'info', action: 'Prefira arquivos com transações individuais para análises mais detalhadas.' });
  }
  if (!data.settings.monthlyGoalCents || !data.settings.ticketGoalCents) insights.push({ title: 'Dê uma direção aos seus resultados', text: 'Uma ou mais metas da loja ainda não foram definidas. Sem elas, os indicadores de atingimento ficam indisponíveis.', tone: 'info', action: user.role === 'admin' ? 'Configure as metas de faturamento e ticket médio.' : 'Solicite ao administrador a definição das metas.' });
  return <><Heading eyebrow="Dados que orientam" title="Insights" description="Leituras objetivas dos seus resultados para apoiar a próxima decisão." /><Notice>As análises são calculadas a partir dos dados importados e das metas configuradas. Projeções são estimativas e dependem do calendário de funcionamento.</Notice>{!analytics.count && <section className="panel"><Empty title="Seus dados têm uma história para contar" icon={<ArrowUpRight size={26} />}>Ainda não há vendas válidas no período. Importe os dados para receber análises de ritmo, ticket e desempenho.</Empty></section>}<div className="insights-grid">{insights.map(insight => <article className={`panel insight-card insight-${insight.tone}`} key={insight.title}><div className="insight-icon">{insight.tone === 'success' ? <ArrowUpRight size={21} /> : insight.tone === 'warning' ? <Target size={21} /> : <Info size={21} />}</div><h2>{insight.title}</h2><p>{insight.text}</p><div className="insight-action"><Check size={15} /><span>{insight.action}</span></div></article>)}</div>{analytics.warnings.length > 0 && <section className="panel"><div className="section-header"><h2>Sobre a qualidade dos dados</h2></div>{analytics.warnings.map((warning, index) => <Notice key={index}>{warning}</Notice>)}</section>}</>;
}

export function HistoryPage(props: ManagementProps) {
  const { data, user } = props; const [reverting, setReverting] = useState<string | null>(null); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const batch = data.batches.find(b => b.id === reverting);
  async function revert() { if (!batch) return; setBusy(true); setError(''); try { const result = await api<{ data: AppData }>(`/api/imports/${batch.id}/revert`, { method: 'POST' }); updateData(result, props); props.notify('Importação revertida. Os indicadores foram recalculados.'); setReverting(null); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } }
  if (user.role !== 'admin') return <section className="panel"><Empty title="Área administrativa">O histórico de importações e de alterações é exclusivo do administrador.</Empty></section>;
  return <><Heading eyebrow="Tudo registrado" title="Histórico e auditoria" description="Rastreabilidade para entender de onde vem cada resultado." /><section className="panel"><div className="section-header"><div><h2>Importações</h2><p className="muted">Arquivos processados e seus efeitos na base</p></div><HistoryIcon size={20} /></div>{!data.batches.length ? <Empty title="Ainda não há importações" icon={<HistoryIcon size={25} />}>Seus arquivos aparecerão aqui após a primeira confirmação de importação.</Empty> : <div className="table-wrap"><table className="data-table"><thead><tr><th>Arquivo / responsável</th><th>Data da importação</th><th>Período dos dados</th><th>Resultado</th><th>Status</th><th /></tr></thead><tbody>{[...data.batches].sort((a, b) => b.importedAt.localeCompare(a.importedAt)).map(b => <tr key={b.id}><td className="product-cell"><strong>{b.filename}</strong><small className="muted">{b.userName} · {b.mode === 'daily' ? 'Diário' : b.mode === 'cumulative' ? 'Acumulado' : 'Consolidado'}</small></td><td>{timestampLabel(b.importedAt)}</td><td className="nowrap">{dateLabel(b.periodStart)}<small className="muted">até {dateLabel(b.periodEnd)}</small></td><td><strong>{b.addedCount} novos · {b.updatedCount} atualizados</strong><small className="muted">{b.ignoredCount} ignorados · {money(b.revenueCents)}</small></td><td><span className={`badge ${b.status === 'confirmed' ? 'badge-success' : 'badge-warning'}`}>{b.status === 'confirmed' ? 'Confirmada' : 'Revertida'}</span></td><td>{b.status === 'confirmed' && <button className="btn btn-ghost" onClick={() => { setError(''); setReverting(b.id); }}>Reverter</button>}</td></tr>)}</tbody></table></div>}</section><section className="panel"><div className="section-header"><h2>Registro de atividades</h2><span className="badge">{data.audit.length} registros</span></div>{!data.audit.length ? <Empty title="Nenhuma atividade registrada">As alterações administrativas serão registradas aqui.</Empty> : <div className="audit-list">{[...data.audit].sort((a, b) => b.at.localeCompare(a.at)).slice(0, 100).map(entry => <div className="audit-row" key={entry.id}><span className="audit-dot" /><div><strong>{entry.action}</strong><p>{entry.details}</p><small className="muted">{entry.userName} · {timestampLabel(entry.at)}</small></div></div>)}</div>}</section>{batch && <Modal title="Reverter esta importação?" onClose={() => { if (!busy) setReverting(null); }}><div className="management-form"><p>Você está prestes a reverter <strong>{batch.filename}</strong>. As vendas e os totais associados serão recalculados. Esta ação ficará registrada na auditoria.</p><Notice>Importações com alterações posteriores dependentes podem ter a reversão bloqueada para proteger a consistência dos dados.</Notice>{error && <p role="alert" className="form-error">{error}</p>}<div className="modal-actions"><button className="btn btn-ghost" disabled={busy} onClick={() => setReverting(null)}>Manter importação</button><button className="btn management-danger-btn" disabled={busy} onClick={revert}>{busy ? 'Revertendo…' : 'Confirmar reversão'}</button></div></div></Modal>}</>;
}

function parseDates(value: string): string[] {
  const values = [...new Set(value.split(/[\s,;]+/).map(s => s.trim()).filter(Boolean))];
  if (values.some(date => !/^\d{4}-\d{2}-\d{2}$/.test(date) || Number.isNaN(Date.parse(`${date}T12:00:00Z`)) || new Date(`${date}T12:00:00Z`).toISOString().slice(0, 10) !== date)) throw new Error('Informe as datas no formato AAAA-MM-DD, separadas por vírgula ou uma por linha.');
  return values.sort();
}

export function SettingsPage(props: ManagementProps) {
  const { data, user } = props; const [settings, setSettings] = useState<Settings>(data.settings); const [monthly, setMonthly] = useState(inputMoney(data.settings.monthlyGoalCents)); const [ticket, setTicket] = useState(inputMoney(data.settings.ticketGoalCents)); const [holidays, setHolidays] = useState(data.settings.holidays.join('\n')); const [openDates, setOpenDates] = useState(data.settings.specialOpenDates.join('\n')); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const [notificationPermission, setNotificationPermission] = useState<NotificationPermission | 'unsupported'>(() => 'Notification' in window ? Notification.permission : 'unsupported');
  const [notificationsEnabled, setNotificationsEnabled] = useState(() => localStorage.getItem('minas-notifications') === 'enabled');
  async function toggleNotifications() {
    if (notificationPermission === 'unsupported') return;
    if (notificationsEnabled) { localStorage.removeItem('minas-notifications'); setNotificationsEnabled(false); props.notify('Notificações do navegador desativadas neste dispositivo.'); return; }
    try {
      const permission = Notification.permission === 'granted' ? 'granted' : await Notification.requestPermission();
      setNotificationPermission(permission);
      if (permission === 'granted') { localStorage.setItem('minas-notifications', 'enabled'); setNotificationsEnabled(true); props.notify('Notificações ativadas neste dispositivo. Mantenha o painel aberto para receber avisos.'); }
      else props.notify(permission === 'denied' ? 'Permissão bloqueada. Você pode permitir notificações nas configurações do navegador.' : 'Permissão não concedida. Os avisos continuam disponíveis no painel.', 'error');
    } catch (err) { props.notify(errorMessage(err), 'error'); }
  }
  useEffect(() => { setSettings(data.settings); setMonthly(inputMoney(data.settings.monthlyGoalCents)); setTicket(inputMoney(data.settings.ticketGoalCents)); setHolidays(data.settings.holidays.join('\n')); setOpenDates(data.settings.specialOpenDates.join('\n')); }, [data.settings]);
  async function save(event: FormEvent) { event.preventDefault(); setBusy(true); setError(''); try { const holidayValues = parseDates(holidays), openValues = parseDates(openDates); if (!settings.companyName.trim()) throw new Error('Informe o nome da empresa.'); if (!settings.workingDays.length && !openValues.length) throw new Error('Selecione ao menos um dia de funcionamento ou uma abertura especial.'); if (holidayValues.some(date => openValues.includes(date))) throw new Error('Uma mesma data não pode ser feriado e abertura especial.'); try { new Intl.DateTimeFormat('pt-BR', { timeZone: settings.timezone }); } catch { throw new Error('Informe um fuso horário válido, como America/Sao_Paulo.'); } const result = await api<{ data: AppData }>('/api/settings', { method: 'PUT', body: JSON.stringify({ ...settings, companyName: settings.companyName.trim(), monthlyGoalCents: currencyValue(monthly), ticketGoalCents: currencyValue(ticket), holidays: holidayValues, specialOpenDates: openValues }) }); updateData(result, props); props.notify('Configurações salvas. Os indicadores foram atualizados.'); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } }
  if (user.role !== 'admin') return <section className="panel"><Empty title="Área administrativa">As configurações da loja são gerenciadas pelo administrador.</Empty></section>;
  return <><Heading eyebrow="Do seu jeito" title="Configurações" description="Organize as regras que dão contexto aos seus números." /><form onSubmit={save} className="settings-form"><section className="panel"><div className="section-header"><div><h2>Identidade e metas</h2><p className="muted">A meta padrão é usada nos meses sem uma meta específica. Defina metas por competência na página Metas.</p></div><Settings2 size={20} /></div><div className="form-grid"><label className="field">Nome da empresa<input required maxLength={80} value={settings.companyName} onChange={e => setSettings(s => ({ ...s, companyName: e.target.value }))} /></label><label className="field">Fuso horário<input readOnly value={settings.timezone} /><small className="muted">Horário de Brasília.</small></label><label className="field">Meta mensal padrão de faturamento (R$)<input required inputMode="decimal" value={monthly} onChange={e => setMonthly(e.target.value)} /></label><label className="field">Meta de ticket médio (R$)<input required inputMode="decimal" value={ticket} onChange={e => setTicket(e.target.value)} /></label></div></section><section className="panel"><div className="section-header"><div><h2>Calendário de funcionamento</h2><p className="muted">Usado no cálculo de dias úteis, meta diária e projeções</p></div><CalendarDays size={20} /></div><fieldset className="working-days"><legend>Dias habituais de funcionamento</legend>{['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'].map((label, day) => <label key={day} className={settings.workingDays.includes(day) ? 'working-day selected' : 'working-day'}><input type="checkbox" checked={settings.workingDays.includes(day)} onChange={e => setSettings(s => ({ ...s, workingDays: e.target.checked ? [...s.workingDays, day].sort() : s.workingDays.filter(d => d !== day) }))} /><span>{label}</span></label>)}</fieldset><div className="form-grid"><label className="field">Feriados e dias sem expediente<textarea rows={5} value={holidays} onChange={e => setHolidays(e.target.value)} placeholder={'2026-12-25\n2027-01-01'} /><small className="muted">Datas AAAA-MM-DD. Uma por linha ou separadas por vírgula.</small></label><label className="field">Aberturas especiais<textarea rows={5} value={openDates} onChange={e => setOpenDates(e.target.value)} placeholder="Adicione uma data fora do calendário habitual" /><small className="muted">Inclui datas que normalmente não seriam dias de funcionamento.</small></label></div></section><section className="panel"><div className="section-header"><div><h2>Alertas e lembretes</h2><p className="muted">Preferências para o acompanhamento dentro do sistema</p></div></div><div className="form-grid"><label className="field">Horário do lembrete<input required type="time" value={settings.reminderTime} onChange={e => setSettings(s => ({ ...s, reminderTime: e.target.value }))} /></label><label className="field">Limite de atenção ao ritmo (%)<input required type="number" min={0} max={100} step={1} value={Math.round(settings.alertThreshold * 100)} onChange={e => setSettings(s => ({ ...s, alertThreshold: Number(e.target.value) / 100 }))} /><small className="muted">Percentual do ritmo esperado abaixo do qual sinalizar atenção.</small></label></div><div className="browser-notifications"><div><strong>Notificações neste navegador</strong><p className="muted">{notificationPermission === 'unsupported' ? 'Este navegador não oferece notificações. Acompanhe os avisos na central do painel.' : notificationPermission === 'denied' ? 'A permissão está bloqueada. Permita notificações nas configurações do navegador para ativar os avisos.' : notificationsEnabled && notificationPermission === 'granted' ? 'Notificações ativadas neste dispositivo.' : 'Receba um aviso quando houver uma nova atualização da operação.'}</p></div><button type="button" className="btn btn-ghost" disabled={notificationPermission === 'unsupported' || (notificationPermission === 'denied' && !notificationsEnabled)} onClick={toggleNotifications}>{notificationsEnabled ? 'Desativar notificações' : 'Ativar notificações do navegador'}</button></div><Notice>Mantenha o painel aberto e o ambiente em execução para receber os avisos. Os lembretes também ficam disponíveis na central do painel.</Notice></section>{error && <p className="form-error" role="alert">{error}</p>}<div className="settings-save"><span className="muted">As alterações recalculam os indicadores da loja.</span><button className="btn btn-primary" type="submit" disabled={busy}><Check size={17} />{busy ? 'Salvando…' : 'Salvar configurações'}</button></div></form></>;
}

const safeSpreadsheet = (value: unknown): string | number => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0;
  const text = String(value ?? ''); return /^[\s]*[=+@-]/.test(text) || /^[\t\r\n]/.test(text) ? `'${text}` : text;
};
function downloadBlob(blob: Blob, filename: string) { const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = filename; document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }

export function ReportsPage(props: ManagementProps) {
  const { data, analytics, period, user, notify } = props; const [busy, setBusy] = useState<string | null>(null);
  const prefix = `minas-cell_${period.from}_${period.to}`;
  const rows = [['Vendedor', 'Faturamento (R$)', 'Vendas', 'Ticket médio (R$)', 'Meta do período (R$)', 'Atingimento (%)'], ...analytics.sellers.filter(m => user.role === 'admin' || m.seller.id === user.sellerId).map(s => [s.seller.name, s.revenueCents / 100, s.count, s.ticketCents / 100, s.goalCents / 100, Number(s.percentage.toFixed(2))])];
  async function exportReport(format: 'csv' | 'xlsx' | 'pdf') {
    setBusy(format);
    try {
      if (format === 'csv') {
        const content = [['Empresa', data.settings.companyName], ['Período', `${period.from} a ${period.to}`], ['Faturamento (R$)', analytics.revenueCents / 100], ['Vendas', analytics.count], ['Ticket médio (R$)', analytics.ticketCents / 100], [], ...rows].map(row => row.map(cell => `"${String(safeSpreadsheet(cell)).replace(/"/g, '""')}"`).join(';')).join('\r\n');
        downloadBlob(new Blob(['\uFEFF', content], { type: 'text/csv;charset=utf-8' }), `${prefix}.csv`);
      } else if (format === 'xlsx') {
        const XLSX = await import('@e965/xlsx'); const workbook = XLSX.utils.book_new();
        const overview = [['Empresa', data.settings.companyName], ['Início do período', period.from], ['Fim do período', period.to], ['Faturamento (R$)', analytics.revenueCents / 100], ['Vendas', analytics.count], ['Ticket médio (R$)', analytics.ticketCents / 100], ['Meta do período (R$)', analytics.goalCents / 100], ['Atingimento (%)', Number(analytics.percentage.toFixed(2))], ['Projeção (R$)', analytics.projectionCents / 100], ['Dados consolidados', analytics.hasSummaries ? 'Sim' : 'Não']];
        const summary = XLSX.utils.aoa_to_sheet(overview.map(row => row.map(safeSpreadsheet))); summary['!cols'] = [{ wch: 26 }, { wch: 40 }]; XLSX.utils.book_append_sheet(workbook, summary, 'Resumo');
        const sheet = XLSX.utils.aoa_to_sheet(rows.map(row => row.map(safeSpreadsheet))); sheet['!cols'] = [{ wch: 28 }, { wch: 22 }, { wch: 12 }, { wch: 22 }, { wch: 26 }, { wch: 20 }]; XLSX.utils.book_append_sheet(workbook, sheet, 'Vendedores');
        const daily = XLSX.utils.aoa_to_sheet([['Data', 'Faturamento (R$)', 'Vendas', 'Ticket médio (R$)'], ...analytics.days.map(d => [d.date, d.revenueCents / 100, d.count, d.ticketCents / 100])]); XLSX.utils.book_append_sheet(workbook, daily, 'Diário');
        XLSX.writeFile(workbook, `${prefix}.xlsx`);
      } else {
        const { jsPDF } = await import('jspdf'); const doc = new jsPDF(); const width = doc.internal.pageSize.getWidth(); let y = 80;
        const header = () => { doc.setFillColor(17, 31, 53); doc.rect(0, 0, width, 52, 'F'); doc.setTextColor(45, 212, 191); doc.setFontSize(10); doc.text('MINAS CELL  /  INTELIGÊNCIA COMERCIAL', 18, 17); doc.setTextColor(255, 255, 255); doc.setFontSize(21); doc.text(data.settings.companyName.slice(0, 55), 18, 30); doc.setFontSize(10); doc.text(`Relatório de vendas | ${dateLabel(period.from)} a ${dateLabel(period.to)}`, 18, 42); doc.setTextColor(30, 41, 59); };
        const line = (text: string, size = 10, bold = false) => { const lines = doc.splitTextToSize(text, width - 36) as string[]; if (y + lines.length * 6 > 278) { doc.addPage(); header(); y = 67; } doc.setFont('helvetica', bold ? 'bold' : 'normal'); doc.setFontSize(size); doc.text(lines, 18, y); y += lines.length * 6 + 3; };
        header(); y = 65; line('RESULTADOS DO PERÍODO', 12, true); line(`Faturamento líquido: ${money(analytics.revenueCents)}    |    Vendas: ${integer(analytics.count)}`); line(`Ticket médio: ${analytics.count ? money(analytics.ticketCents) : 'Sem vendas'}    |    Meta: ${analytics.goalCents ? money(analytics.goalCents) : 'Não definida'}`); line(`Atingimento: ${analytics.goalCents ? percent(analytics.percentage) : 'Sem meta'}    |    Dias úteis: ${analytics.workingDays}`); y += 5; line('DESEMPENHO POR VENDEDOR', 12, true);
        if (!analytics.sellers.length) line('Nenhum vendedor com resultados no período.');
        analytics.sellers.filter(m => user.role === 'admin' || m.seller.id === user.sellerId).forEach(s => { line(s.seller.name, 11, true); line(`${money(s.revenueCents)} | ${integer(s.count)} vendas | Ticket ${s.count ? money(s.ticketCents) : 'indisponível'} | Meta ${s.goalCents ? percent(s.percentage) : 'não definida'}`); });
        y += 5; line('CRITÉRIOS DO RELATÓRIO', 11, true); line('Valores líquidos de vendas válidas. Cancelamentos e devoluções são desconsiderados. A contagem utiliza transações identificadas e os totais de relatórios consolidados, quando presentes.'); if (analytics.hasSummaries) line('Este período inclui dados consolidados, sem detalhamento individual completo.'); analytics.warnings.forEach(warning => line(warning)); line(`Emitido em ${new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short', timeZone: data.settings.timezone }).format(new Date())} (${data.settings.timezone}).`); for (let n = 1; n <= doc.getNumberOfPages(); n++) { doc.setPage(n); doc.setFontSize(8); doc.setTextColor(100, 116, 139); doc.text(`Minas Cell | ${n} de ${doc.getNumberOfPages()}`, 18, 288); } doc.save(`${prefix}.pdf`);
      }
      notify('Relatório gerado com os dados do período.');
    } catch (err) { notify(errorMessage(err), 'error'); } finally { setBusy(null); }
  }
  return <><Heading eyebrow="Resultados para compartilhar" title="Relatórios" description="Seus números organizados para a próxima reunião ou decisão." /><section className="panel report-overview"><div><span className="eyebrow">Período do relatório</span><h2>{dateLabel(period.from)} <span className="muted">a</span> {dateLabel(period.to)}</h2><p className="muted">{data.settings.companyName} · {user.role === 'admin' ? 'Visão da loja' : 'Seus resultados'}</p></div><CalendarDays size={30} /></section><div className="stat-grid management-three"><Metric label="Faturamento líquido" value={money(analytics.revenueCents)} /><Metric label="Vendas válidas" value={integer(analytics.count)} /><Metric label="Ticket médio" value={analytics.count ? money(analytics.ticketCents) : '—'} /></div><div className="report-formats">{[{ id: 'pdf' as const, name: 'Relatório em PDF', icon: <FileText size={28} />, description: 'Resumo executivo com identidade da loja, indicadores e desempenho dos vendedores.', label: 'Baixar PDF' }, { id: 'xlsx' as const, name: 'Planilha Excel', icon: <FileSpreadsheet size={28} />, description: 'Resumo, indicadores por vendedor e visão diária em abas para aprofundar sua análise.', label: 'Baixar Excel' }, { id: 'csv' as const, name: 'Dados em CSV', icon: <FileText size={28} />, description: 'Resumo e resultados por vendedor em formato aberto, compatível com planilhas.', label: 'Baixar CSV' }].map(format => <section className="panel report-format" key={format.id}><div className="report-format-icon">{format.icon}</div><h2>{format.name}</h2><p className="muted">{format.description}</p><button className="btn btn-ghost" disabled={busy !== null} onClick={() => exportReport(format.id)}><ArrowDownToLine size={16} />{busy === format.id ? 'Gerando…' : format.label}</button></section>)}</div>{!analytics.count && <Notice>Não há vendas válidas no período. Os relatórios serão gerados com os totais zerados e a configuração atual, sem preencher dados ausentes.</Notice>}{analytics.hasSummaries && <Notice>O período contém valores consolidados. A disponibilidade do detalhamento depende dos arquivos importados.</Notice>}</>;
}
